# runtime module: common

import json
import re

TOKEN = re.compile(r"\{([A-Za-z0-9_.:]+)\}")


def decode(value):

    if isinstance(value, str):
        text = value.strip()
        if text[:1] in ("[", "{"):
            try:
                return json.loads(text)
            except Exception:
                return value
    return value


def walk(value, parts):

    for part in parts:
        value = decode(value)
        if isinstance(value, dict) and part in value:
            value = value.get(part)
        elif isinstance(value, list) and part.isdigit() and int(part) < len(value):
            value = value[int(part)]
        else:
            return False, None
    return True, value


def lookup(state, key):





    if not isinstance(state, dict) or key is None:
        return None
    key = str(key)
    if key in state:
        return state.get(key)
    parts = key.split(".")
    cut = len(parts) - 1
    while cut > 0:
        head = ".".join(parts[:cut])
        if head in state:
            found, value = walk(state.get(head), parts[cut:])
            if found:
                return value
        cut -= 1
    return None


def is_true(value):

    return value is True or (isinstance(value, str) and value.strip().lower() == "true")


def is_false(value):

    return value is False or (isinstance(value, str) and value.strip().lower() == "false")


def is_missing(value):

    return value is None or (isinstance(value, str) and value.strip() == "")


def to_float(value):

    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    try:
        return float(str(value).strip())
    except Exception:
        return None


def to_int(value, default=0):

    number = to_float(value)
    if number is None:
        return default
    try:
        return int(number)
    except Exception:
        return default










def as_text(value):

    if value is None:
        return ""
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, float):
        try:
            if value == int(value):
                return str(int(value))
        except Exception:
            return str(value)
    return str(value)


def check(value, op, arg=None):




    if op == "true":
        return is_true(value)
    if op == "false":
        return is_false(value)
    if op == "missing":
        return is_missing(value)
    if op == "present":
        return not is_missing(value)
    if op in ("equals", "not_equals"):
        same = value is not None and as_text(value) == as_text(arg)
        return same if op == "equals" else not same
    if op in ("in", "not_in"):
        options = [as_text(x) for x in (arg if isinstance(arg, list) else [arg])]
        inside = value is not None and as_text(value) in options
        return inside if op == "in" else not inside
    if op == "contains":
        return value is not None and as_text(arg).lower() in as_text(value).lower()
    if op in ("lt", "lte", "gt", "gte"):
        return compare(to_float(value), op, to_float(arg))
    return False


def compare(left, op, right):

    if left is None or right is None:
        return False
    if op == "lt":
        return left < right
    if op == "lte":
        return left <= right
    if op == "gt":
        return left > right
    return left >= right


def holds(conditions, get):

    for cond in conditions or []:
        arg = cond[2] if len(cond) > 2 else None
        if not check(get(cond[0]), cond[1], arg):
            return False
    return True


def fill(template, get):

    def one(match):
        return as_text(get(match.group(1)))
    return TOKEN.sub(one, as_text(template))


def split_csv(text):

    return [part.strip() for part in as_text(text).split(",") if part.strip()]


def add_csv(text, item):

    items = split_csv(text)
    if item not in items:
        items.append(item)
    return ",".join(items)


def var_key(text):

    return re.sub(r"[^A-Za-z0-9_]", "_", as_text(text))

# runtime module: hooks













import datetime
import re






































































































































































































































































































































































































def record_success(state, tool, key, cfg):

    state["bb_count__" + tool] = to_int(state.get("bb_count__" + tool)) + 1
    if key:
        state["bb_done__" + tool] = add_csv(state.get("bb_done__" + tool), key)
    prefix = "bb_arg__" + tool + "__"
    for name in list(state.keys()):
        if str(name).startswith(prefix):
            state["bb_last__" + tool + "__" + str(name)[len(prefix):]] = state.get(name)
    for field in cfg.get("log_fields", []):
        value = clean_entry(state.get(prefix + var_key(field)))
        log = "bb_log__" + tool + "__" + var_key(field)
        state[log] = add_csv(state.get(log), clean_entry(key) + ":" + value)


def clean_entry(value):

    return as_text(value).replace(",", " ").replace(":", " ")


def open_items(state, tools):

    done = []
    for tool in tools:
        done = done + split_csv(state.get("bb_done__" + tool))
    items = [item for item in split_csv(state.get("bb_products")) if item not in done]
    return ", ".join(items) if items else "none"


def record_failure(state, tool, key, cfg):

    counter = "bb_fail__" + tool + "__" + var_key(key or "-")
    failures = to_int(state.get(counter)) + 1
    state[counter] = failures
    state["bb_count__" + tool] = to_int(state.get("bb_count__" + tool))
    if failures > to_int(cfg.get("retries")):
        state["bb_failed_out__" + tool] = add_csv(state.get("bb_failed_out__" + tool), key or "-")
    return failures


def data_getter(data):

    def get(name):
        return lookup(data, name)
    return get


def first_rule(cfg, data):

    for rule in cfg.get("rules", []):
        if holds(rule.get("when"), data_getter(data)):
            return rule
    return None


def choose_message(cfg, service_ok, data, tracked, success, failures):

    messages = cfg.get("messages", dict())
    if service_ok:
        rule = first_rule(cfg, data)
        if rule is not None:
            return rule.get("say", ""), rule.get("set", dict())
    if tracked:
        if success:
            return messages.get("ok", ""), dict()
        if failures > to_int(cfg.get("retries")):
            return messages.get("give_up", ""), dict()
        return messages.get("retry", ""), dict()
    if not service_ok:
        return messages.get("error", ""), dict()
    return messages.get("default", ""), dict()


def run_post(state, result, cfg):

    tool = cfg.get("tool", "tool")
    try:
        if not isinstance(result, dict):
            return
        if cfg.get("strip_header", True):
            result.pop("header", None)
        data = decode(result.get("data"))
        if isinstance(data, dict):
            result["data"] = data
        service_ok = isinstance(data, dict) and as_text(result.get("status") or "success") == "success"
        key = as_text(state.get("bb_key__" + tool))
        if not key and cfg.get("key_field"):
            key = as_text(lookup(state, tool + "_args." + cfg.get("key_field")))
        tracked = bool(cfg.get("ok_when"))
        success = (service_ok and holds(cfg.get("ok_when"), data_getter(data))) if tracked else service_ok
        failures = 0
        if tracked and success:
            record_success(state, tool, key, cfg)
        elif tracked:
            failures = record_failure(state, tool, key, cfg)
            mark = cfg.get("fail_mark")
            if mark and isinstance(data, dict):
                data[mark[0]] = mark[1]
