import json
import re




def decode(value):

    if isinstance(value, str):
        text = value.strip()
        if text[:1] in ("[", "{"):
            try:
                return json.loads(text)
            except Exception:
                return value
    return value


def walk(value, parts):

    for part in parts:
        value = decode(value)
        if isinstance(value, dict) and part in value:
            value = value.get(part)
        elif isinstance(value, list) and part.isdigit() and int(part) < len(value):
            value = value[int(part)]
        else:
            return False, None
    return True, value


def lookup(state, key):





    if not isinstance(state, dict) or key is None:
        return None
    key = str(key)
    if key in state:
        return state.get(key)
    parts = key.split(".")
    cut = len(parts) - 1
    while cut > 0:
        head = ".".join(parts[:cut])
        if head in state:
            found, value = walk(state.get(head), parts[cut:])
            if found:
                return value
        cut -= 1
    return None
















































def as_text(value):

    if value is None:
        return ""
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, float):
        try:
            if value == int(value):
                return str(int(value))
        except Exception:
            return str(value)
    return str(value)







































































def var_key(text):

    return re.sub(r"[^A-Za-z0-9_]", "_", as_text(text))

