        if str(name).startswith(prefix):
            state.pop(name, None)
    for name in body:
        state[prefix + var_key(name)] = body[name]
    state["bb_adjusted__" + tool] = "; ".join(notes)
    state["bb_key__" + tool] = key
    state["bb_pre_error__" + tool] = "; ".join(errors)




































































































































