    return name + " changed from " + old + " to " + new + " (" + why + ")"


def normalize_field(body, name, spec, today):

    if name not in body:
        return
    chosen = spec.get("cases", dict()).get(as_text(body.get(spec.get("by")))) if spec.get("by") else spec
